<?php
require_once "../config/auth.php";
require_once "../config/database.php";
wajib_login(['wali_kelas']);

$uid=(int)($_SESSION['user_id']??0); $ok=''; $err='';
@mysqli_query($conn,"ALTER TABLE users ADD COLUMN profile_photo VARCHAR(255) DEFAULT NULL");
@mysqli_query($conn,"CREATE TABLE IF NOT EXISTS pengaturan (id INT AUTO_INCREMENT PRIMARY KEY,nama_kelas VARCHAR(100) NOT NULL DEFAULT 'XI TJKT 2',tahun_pelajaran VARCHAR(30) NOT NULL DEFAULT '2026 / 2027',nama_sekolah VARCHAR(150) NOT NULL DEFAULT 'SMK PGRI Subang',logo VARCHAR(255) DEFAULT NULL,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP)");
@mysqli_query($conn,"INSERT INTO pengaturan (id) VALUES (1) ON DUPLICATE KEY UPDATE id=id");

$q=mysqli_prepare($conn,"SELECT nama,username,password,profile_photo FROM users WHERE id=? AND role='wali_kelas' LIMIT 1"); mysqli_stmt_bind_param($q,'i',$uid); mysqli_stmt_execute($q); mysqli_stmt_bind_result($q,$nama,$username,$hash,$photo); if(!mysqli_stmt_fetch($q)) die('Akun wali kelas tidak ditemukan.'); mysqli_stmt_close($q);
$r=mysqli_query($conn,"SELECT * FROM pengaturan WHERE id=1"); $cfg=mysqli_fetch_assoc($r)?:[];
$kelas=$cfg['nama_kelas']??'XI TJKT 2'; $tahun=$cfg['tahun_pelajaran']??'2026 / 2027'; $sekolah=$cfg['nama_sekolah']??'SMK PGRI Subang';
if(empty($_SESSION['csrf_settings'])) $_SESSION['csrf_settings']=bin2hex(random_bytes(32)); $csrf=$_SESSION['csrf_settings'];

if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!hash_equals($csrf,$_POST['csrf_token']??'')) $err='Permintaan tidak valid. Muat ulang halaman.';
 else {
  $action=$_POST['action']??'';
  if($action==='account'){
   $n=trim($_POST['nama']??''); $u=trim($_POST['username']??''); $old=$_POST['old_password']??''; $np=$_POST['new_password']??''; $cp=$_POST['confirm_password']??'';
   if($n===''||$u==='') $err='Nama dan username wajib diisi.'; elseif(strlen($u)<3||strlen($u)>50) $err='Username harus 3–50 karakter.'; elseif(!password_verify($old,$hash)) $err='Password lama salah.';
   else { $c=mysqli_prepare($conn,"SELECT id FROM users WHERE username=? AND id<>? LIMIT 1"); mysqli_stmt_bind_param($c,'si',$u,$uid); mysqli_stmt_execute($c); mysqli_stmt_store_result($c); $taken=mysqli_stmt_num_rows($c)>0; mysqli_stmt_close($c);
    if($taken) $err='Username tersebut sudah digunakan.'; elseif($np!==''&&strlen($np)<8) $err='Password baru minimal 8 karakter.'; elseif($np!==''&&$np!==$cp) $err='Konfirmasi password tidak cocok.';
    else { if($np!==''){ $nh=password_hash($np,PASSWORD_DEFAULT); $x=mysqli_prepare($conn,"UPDATE users SET nama=?,username=?,password=? WHERE id=?"); mysqli_stmt_bind_param($x,'sssi',$n,$u,$nh,$uid); } else { $x=mysqli_prepare($conn,"UPDATE users SET nama=?,username=? WHERE id=?"); mysqli_stmt_bind_param($x,'ssi',$n,$u,$uid); } if(mysqli_stmt_execute($x)){$_SESSION['nama']=$n;$_SESSION['username']=$u;$nama=$n;$username=$u;if($np!=='')$hash=$nh;$ok='Data akun berhasil diperbarui.';}else $err='Gagal memperbarui akun.'; mysqli_stmt_close($x); }
   }
  }
  if($action==='profile'){
   $n=trim($_POST['nama_profile']??''); $has=isset($_FILES['foto'])&&$_FILES['foto']['error']!==UPLOAD_ERR_NO_FILE;
   if($n==='') $err='Nama wali kelas wajib diisi.'; elseif(!$has){$x=mysqli_prepare($conn,"UPDATE users SET nama=? WHERE id=?");mysqli_stmt_bind_param($x,'si',$n,$uid);if(mysqli_stmt_execute($x)){$_SESSION['nama']=$n;$nama=$n;$ok='Profil wali kelas diperbarui.';}else $err='Gagal memperbarui profil.';mysqli_stmt_close($x);}
   elseif($_FILES['foto']['error']!==UPLOAD_ERR_OK) $err='Upload foto gagal.'; elseif($_FILES['foto']['size']>2097152) $err='Ukuran foto maksimal 2 MB.';
   else { $tmp=$_FILES['foto']['tmp_name']; $mime=function_exists('mime_content_type')?mime_content_type($tmp):''; $map=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp']; if(!isset($map[$mime]))$err='Format foto harus JPG, PNG, atau WEBP.'; else {$dir=__DIR__.'/../uploads/profile';if(!is_dir($dir))mkdir($dir,0755,true);$f='wali_'.$uid.'_'.bin2hex(random_bytes(6)).'.'.$map[$mime];$dest=$dir.'/'.$f;if(!move_uploaded_file($tmp,$dest))$err='Foto tidak dapat disimpan.';else{$x=mysqli_prepare($conn,"UPDATE users SET nama=?,profile_photo=? WHERE id=?");mysqli_stmt_bind_param($x,'ssi',$n,$f,$uid);if(mysqli_stmt_execute($x)){if($photo&&is_file($dir.'/'.$photo))@unlink($dir.'/'.$photo);$_SESSION['nama']=$n;$nama=$n;$photo=$f;$ok='Profil dan foto berhasil diperbarui.';}else{@unlink($dest);$err='Gagal memperbarui profil.';}mysqli_stmt_close($x);}}}
  }
  if($action==='class'){$kelas=trim($_POST['nama_kelas']??'');$tahun=trim($_POST['tahun_pelajaran']??'');$sekolah=trim($_POST['nama_sekolah']??'');if($kelas===''||$tahun===''||$sekolah==='')$err='Data kelas wajib diisi.';else{$x=mysqli_prepare($conn,"INSERT INTO pengaturan(id,nama_kelas,tahun_pelajaran,nama_sekolah) VALUES(1,?,?,?) ON DUPLICATE KEY UPDATE nama_kelas=VALUES(nama_kelas),tahun_pelajaran=VALUES(tahun_pelajaran),nama_sekolah=VALUES(nama_sekolah)");mysqli_stmt_bind_param($x,'sss',$kelas,$tahun,$sekolah);if(mysqli_stmt_execute($x))$ok='Pengaturan kelas berhasil disimpan.';else$err='Gagal menyimpan pengaturan kelas.';mysqli_stmt_close($x);}}
 }
}
$img=$photo?'../uploads/profile/'.rawurlencode($photo):'';
?>
