<div class="grid"><section class="card"><h2><i class="fa-solid fa-shield-halved"></i> Akun & Keamanan</h2><p class="desc">Ganti username dan password login wali kelas.</p><form method="post"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars($csrf)?>"><input type="hidden" name="action" value="account"><div class="field"><label>Nama akun</label><input name="nama" value="<?=htmlspecialchars($nama)?>" required></div><div class="field"><label>Username</label><input name="username" value="<?=htmlspecialchars($username)?>" required></div><div class="field"><label>Password lama</label><input type="password" name="old_password" required></div><div class="field"><label>Password baru <span style="font-weight:normal">(kosong = tetap)</span></label><input type="password" name="new_password" minlength="8"></div><div class="field"><label>Konfirmasi password baru</label><input type="password" name="confirm_password" minlength="8"></div><button class="btn">Simpan Akun</button></form></section>
<section class="card"><h2><i class="fa-solid fa-user-tie"></i> Profil Wali Kelas</h2><p class="desc">Foto profil akan tampil di dashboard.</p><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars($csrf)?>"><input type="hidden" name="action" value="profile"><?php if($img):?><img class="avatar" src="<?=$img?>" alt="Foto wali kelas"><?php else:?><div class="avatar-empty"><i class="fa-solid fa-user-tie"></i></div><?php endif;?><div class="field"><label>Nama wali kelas</label><input name="nama_profile" value="<?=htmlspecialchars($nama)?>" required></div><div class="field"><label>Foto profil</label><input type="file" name="foto" accept="image/jpeg,image/png,image/webp"></div><div class="note">JPG, PNG, WEBP • maksimal 2 MB.</div><br><button class="btn">Simpan Profil</button></form></section>
<section class="card full"><h2><i class="fa-solid fa-school"></i> Identitas Kelas</h2><p class="desc">Data identitas yang ditampilkan pada sistem kelas.</p><form method="post"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars($csrf)?>"><input type="hidden" name="action" value="class"><div class="grid"><div class="field"><label>Nama kelas</label><input name="nama_kelas" value="<?=htmlspecialchars($kelas)?>" required></div><div class="field"><label>Tahun pelajaran</label><input name="tahun_pelajaran" value="<?=htmlspecialchars($tahun)?>" required></div><div class="field"><label>Nama sekolah</label><input name="nama_sekolah" value="<?=htmlspecialchars($sekolah)?>" required></div></div><button class="btn">Simpan Identitas Kelas</button></form></section></div></div></body></html>
